"""Writes from an unconfirmed email are refused (generated by Shikshya, PX.303). A POST, PUT, PATCH
or DELETE under /api/ signed with the token of a user who has a pending address gets a plain 403 with the code
email_unverified, so they cannot book or pay until they open the link. The sign-in routes under /api/auth/ stay open
(sign-out, the profile, the link and a resend); reading works; a request without a token is left to the view."""
from django.http import JsonResponse
from knox.auth import TokenAuthentication
from knox.settings import knox_settings
from rest_framework import exceptions
from rest_framework.request import Request

from .core import needs

SAFE = ("GET", "HEAD", "OPTIONS", "TRACE")
OPEN = "/api/auth/"
REFUSED = {"detail": "Please confirm your email first: open the link we sent you, or ask for a new one.",
           "code": "email_unverified"}


def held(request):
    """True for a write by a signed-in user whose email is not confirmed yet."""
    if request.method in SAFE or not request.path.startswith("/api/") or request.path.startswith(OPEN):
        return False
    prefix = knox_settings.AUTH_HEADER_PREFIX + " "
    if not request.META.get("HTTP_AUTHORIZATION", "").startswith(prefix):
        return False
    try:
        found = TokenAuthentication().authenticate(Request(request))
    except exceptions.APIException:
        return False
    return bool(found) and needs(found[0])


class VerifiedWritesMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        if held(request):
            return JsonResponse(REFUSED, status=403)
        return self.get_response(request)
